UPDATE runtime_message_inbox SET status='CLAIMED', claim_epoch=claim_epoch+1, lease_until=#{until}, updated_at=#{now}
WHERE id=#{id} AND claim_epoch=#{epoch}
  AND (status='PENDING' OR (status='CLAIMED' AND lease_until < #{now}))

UPDATE runtime_message_inbox SET status=#{status}, error_code=#{error,jdbcType=VARCHAR},
  lease_until=NULL, next_attempt_at=#{next}, updated_at=#{now}
WHERE id=#{id} AND claim_epoch=#{epoch} AND status='CLAIMED'
